INSERT OR REPLACE INTO articles (
  slug, title, subtitle, term, aliases_json, format,
  reading_time_minutes, short_definition, origin_label,
  cover_gradient, cover_image, accent_badge, published_at,
  related_book_slugs_json, sort_order, is_published
) VALUES (
  'residu-atensi', 'Residu Atensi: Harga Mahal Multitasking', 'Mengapa sekadar melirik pesan masuk selama sepuluh detik diam-diam melumpuhkan ketajaman berpikir Anda hingga belasan menit berikutnya.', 'Residu Atensi', '["Residu Atensi","Attention Residue","Task Switching"]', 'bedah-istilah',
  4, 'Sisa perhatian kognitif yang tetap melekat pada tugas sebelumnya setelah seseorang berpindah ke tugas baru, sehingga menurunkan ketajaman fokus dan kualitas berpikir pada pekerjaan berikutnya.', 'Sophie Leroy (2009) → Cal Newport (2016)',
  'from-slate-950 via-violet-950 to-purple-950', '/images/articles/residu-atensi.svg', 'Bedah Istilah', '2026-11-28',
  '["deep-work","make-time","essentialism"]', 12, 1
);
INSERT OR REPLACE INTO article_contents (
  article_slug, lead_paragraph, sections_json, key_takeaways_json
) VALUES (
  'residu-atensi',
  'Bayangkan Anda sedang menyusun strategi presentasi penting atau membedah laporan keuangan yang rumit. Tiba-tiba ponsel di samping laptop menyala menandakan pesan grup masuk, lalu Anda membukanya sebentar selama sepuluh detik sekadar membaca tanpa membalas. Anda merasa tidak kehilangan waktu berarti dan langsung kembali menatap layar utama. Namun anehnya, kalimat berikutnya terasa jauh lebih berat dirangkai—seolah-olah separuh otak Anda baru saja tersedot pergi.',
  '[{"heading":"Eksperimen Sophie Leroy dan Ilusi Berpindah Cepat","paragraphs":["Perasaan buntu setelah melirik gangguan singkat itu bukan sekadar kurang kopi, melainkan fenomena kognitif yang diteliti profesor bisnis Sophie Leroy pada 2009. Dalam serangkaian eksperimen di laboratorium, Leroy meminta para peserta mengerjakan dua tugas analitis secara berurutan. Sebagian peserta diberi kesempatan menuntaskan tugas pertama sebelum berpindah, sementara kelompok lain langsung dipotong di tengah jalan untuk mengerjakan tugas kedua.","Hasilnya menunjukkan pola yang konsisten: kelompok yang dipotong di tengah jalan tampil jauh lebih buruk pada tugas kedua, meskipun mereka merasa sudah sepenuhnya mengalihkan perhatian. Ketika tugas pertama belum tuntas, otak tidak pernah benar-benar menutup berkasnya. Sebagian kapasitas memori kerja tetap aktif memikirkan persoalan lama itu di latar belakang.","Leroy menamai sisa keterikatan mental tersebut sebagai Attention Residue atau Residu Atensi. Alih-alih berpindah secara bersih seperti sakelar lampu, perhatian manusia bergerak lambat dan lengket setiap kali dipaksa melompat dari satu konteks ke konteks lain."],"highlightBox":{"label":"Hukum Residu Atensi","text":"Setiap kali Anda berpindah dari Tugas A ke Tugas B sebelum Tugas A selesai, sebagian perhatian Anda tertinggal di Tugas A dan memotong kapasitas berpikir Anda pada Tugas B."}},{"heading":"Mengapa Sekadar Mengintip Pesan Merusak Fokus Mendalam","paragraphs":["Temuan Leroy menjadi salah satu fondasi utama buku Deep Work karya Cal Newport. Menurut Newport, banyak pekerja pengetahuan modern merasa produktif karena terus sibuk merespons surel dan pesan instan sepanjang hari. Padahal, kebiasaan memeriksa kotak masuk setiap sepuluh atau lima belas menit membuat seseorang berada dalam kondisi residu atensi permanen.","Setiap lirikan singkat memicu siklus pergantian konteks baru. Bahkan ketika Anda tidak membalas pesan tersebut, otak tetap memproses implikasinya: apakah ini mendesak, siapa pengirimnya, dan apa yang harus dilakukan nanti. Akibatnya, kemampuan berpikir mendalam yang dibutuhkan untuk memecahkan masalah kompleks tidak pernah sempat mencapai kecepatan puncaknya.","Dalam Make Time, Jake Knapp dan John Zeratsky menyebut aplikasi obrolan, umpan berita, dan media sosial sebagai Infinity Pools—kolam konten tanpa dasar yang selalu menawarkan pembaruan instan. Sekali keran notifikasi dibiarkan terbuka di meja kerja, residu atensi akan mengikis jam-jam paling berharga kita tanpa meninggalkan jejak yang terasa di permukaan."]},{"heading":"Biaya Tersembunyi di Budaya Kerja Serba Responsif","paragraphs":["Tantangan terbesar melawan residu atensi sering kali bukan datang dari kemalasan pribadi, melainkan norma tak tertulis di tempat kerja. Banyak organisasi tanpa sadar menyamakan kecepatan membalas pesan dengan dedikasi kerja. Karyawan yang selalu siaga di ruang obrolan dipuji responsif, sementara waktu hening untuk berpikir utuh dianggap kemewahan.","Greg McKeown dalam Essentialism mengingatkan bahwa ketika segala hal diperlakukan sama pentingnya, tidak ada satu pun yang benar-benar dikerjakan secara luar biasa. Mengorbankan dua jam kerja fokus demi membalas belasan pesan remeh dalam hitungan detik sebenarnya menukar pekerjaan bernilai tinggi dengan kesibukan bernilai rendah.","Ironisnya, residu atensi juga membuat pekerjaan yang seharusnya selesai dalam satu jam molor menjadi tiga jam penuh kesalahan kecil. Pada akhirnya, pekerja pulang dengan rasa lelah luar biasa meski merasa belum menghasilkan terobosan berarti."]},{"heading":"Cara Praktis Membersihkan Residu Atensi Harian","paragraphs":["Kabar baiknya, residu atensi dapat dikendalikan dengan merancang ulang cara kita berpindah tugas. Langkah pertama adalah mengumpulkan pengecekan pesan dalam blok waktu tertentu, misalnya dua atau tiga kali sehari, alih-alih membiarkan notifikasi menyala terus-menerus. Ketika sedang masuk sesi Deep Work, jauhkan ponsel dari jangkauan pandang dan tutup tab komunikasi.","Langkah kedua yang sangat efektif saat Anda terpaksa berhenti di tengah pekerjaan yang belum selesai adalah menulis catatan singkat penutup. Tuliskan dalam satu atau dua kalimat di mana posisi terakhir Anda dan apa langkah pertama yang akan dilakukan saat kembali nanti. Penelitian lanjutan menunjukkan bahwa memberi ''titik jeda jelas'' membantu otak melepaskan beban ingatan sementara sehingga residu atensi berkurang drastis.","Terakhir, biasakan memilih satu prioritas utama setiap hari sebelum membuka kotak masuk pagi hari. Dengan melindungi sembilan puluh menit pertama untuk pekerjaan paling menuntut nalar tanpa gangguan, Anda memberi kesempatan bagi pikiran untuk bekerja pada kapasitas penuhnya."]}]',
  '["Residu Atensi terjadi ketika sebagian perhatian masih tertinggal pada tugas sebelumnya sehingga menurunkan performa pada tugas baru.","Sekadar melirik pesan masuk selama beberapa detik sudah cukup memicu residu atensi yang mengganggu fokus selama belasan menit.","Menggabungkan pengecekan pesan dalam jadwal khusus (batching) melindungi blok waktu Deep Work dari perpecahan fokus.","Menulis catatan langkah berikutnya sebelum menjeda pekerjaan membantu otak menutup konteks lama secara bersih."]'
);

INSERT OR REPLACE INTO articles (
  slug, title, subtitle, term, aliases_json, format,
  reading_time_minutes, short_definition, origin_label,
  cover_gradient, cover_image, accent_badge, published_at,
  related_book_slugs_json, sort_order, is_published
) VALUES (
  'mvp-vs-obsesi-kesempurnaan', 'MVP vs Obsesi Kesempurnaan dalam Bisnis', 'Kapan tim harus segera meluncurkan produk setengah jadi untuk menguji pasar, dan kapan kualitas justru tidak boleh dikompromikan.', 'Produk Minimum Layak', '["Produk Minimum Layak","Minimum Viable Product","Validated Learning"]', 'lintas-buku',
  4, 'Versi paling sederhana dari suatu produk yang tetap berfungsi utuh untuk menguji hipotesis bisnis terpenting di pasar nyata dengan biaya dan waktu seminimal mungkin.', 'Eric Ries (2011) · Jim Collins (2001) · Clayton Christensen (1997)',
  'from-slate-950 via-amber-950 to-orange-950', '/images/articles/mvp-vs-obsesi-kesempurnaan.svg', 'Lintas Buku', '2026-11-28',
  '["the-lean-startup","good-to-great","the-innovators-dilemma"]', 11, 1
);
INSERT OR REPLACE INTO article_contents (
  article_slug, lead_paragraph, sections_json, key_takeaways_json
) VALUES (
  'mvp-vs-obsesi-kesempurnaan',
  'Di hampir setiap tim produk dan pendiri usaha, selalu ada tarik-menarik sengit antara dua kubu: kelompok yang ingin segera merilis versi awal ke pasar, dan kelompok yang bersikeras memoles setiap detail sampai terasa sempurna. Terlalu lama bersembunyi di balik ruang pengembangan membuat bisnis kehabisan napas sebelum sempat bertemu pelanggan nyata. Namun di sisi lain, tergesa-gesa melempar produk yang rapuh juga dapat menghancurkan reputasi yang susah payah dibangun.',
  '[{"heading":"Jebakan Merancang Produk Sempurna di Ruang Tertutup","paragraphs":["Banyak tim memulai proyek baru dengan keyakinan bahwa produk hebat pasti langsung disambut pasar begitu diluncurkan. Mereka menyusun daftar fitur puluhan halaman, menyempurnakan antarmuka berbulan-bulan, lalu menjaga semuanya serba rahasia hingga hari peluncuran tiba. Masalahnya, terlalu sering hari peluncuran justru disambut kesunyian karena asumsi paling mendasar tentang masalah pelanggan ternyata meleset.","Kegagalan semacam ini bukan disebabkan kurangnya kerja keras atau kecerdasan teknis tim, melainkan karena seluruh energi dicurahkan untuk mengeksekusi rencana tanpa pernah memvalidasi apakah rencana itu diinginkan pasar. Semakin banyak fitur yang dibangun sebelum diuji pengguna nyata, semakin besar pula biaya emosional dan finansial ketika tim harus mengakui bahwa arah produknya keliru."]},{"heading":"Makna Sejati MVP dan Validated Learning","paragraphs":["Dalam The Lean Startup, Eric Ries memperkenalkan konsep Produk Minimum Layak atau Minimum Viable Product sebagai penawar dari pemborosan tersebut. MVP bukanlah produk cacat yang dilempar asal jalan ke publik, melainkan eksperimen terkecil yang mampu memutar siklus bangun-ukur-belajar secepat mungkin. Tujuannya bukan sekadar mencetak penjualan awal, melainkan memperoleh validated learning—pembelajaran terukur dari perilaku nyata pengguna.","Gagasan ini beresonansi kuat dengan temuan Clayton Christensen dalam The Innovator''s Dilemma. Banyak inovasi disruptif awalnya terlihat terlalu sederhana, bahkan diremehkan oleh perusahaan mapan dan pelanggan kelas atasnya. Namun justru kesederhanaan itulah yang memungkinkan pendatang baru bergerak lincah, mendengar keluhan pengguna pinggiran, dan menyempurnakan teknologi mereka jauh lebih cepat daripada raksasa industri.","Ketika sebuah tim merilis versi sederhana secara sadar, mereka sebenarnya sedang membeli kejelasan dengan harga paling murah. Alih-alih berdebat di ruang rapat tentang fitur mana yang paling disukai pengguna, data penggunaan aktual langsung menjawab hipotesis tersebut dalam hitungan hari."],"highlightBox":{"label":"Makna Sejati MVP","text":"Produk Minimum Layak bukanlah produk setengah rusak yang mengabaikan pengguna, melainkan versi paling ringkas yang cukup utuh untuk membuktikan satu hipotesis nilai terpenting di dunia nyata."}},{"heading":"Kapan Obsesi Kualitas Tidak Boleh Ditawar","paragraphs":["Meski begitu, jargon bergerak cepat dan merusak hal-hal lama sering disalahartikan menjadi pembenaran atas produk yang ceroboh. Dalam riset jangka panjangnya pada Good to Great, Jim Collins menemukan bahwa perusahaan yang bertahan unggul puluhan tahun tidak dibangun di atas eksperimen serampangan, melainkan disiplin eksekusi yang konsisten dan obsesi menjaga standar inti.","Perbedaan konteks sangat menentukan batas toleransi pengguna terhadap produk versi awal. Pada aplikasi catatan pribadi atau fitur eksperimental berisiko rendah, pengguna biasanya memaafkan tampilan yang sederhana asalkan masalah utamanya terpecahkan. Sebaliknya, pada layanan keuangan, kesehatan, keamanan data, atau infrastruktur bisnis, satu kegagalan kecil saja sudah cukup untuk memutus kepercayaan pelanggan selamanya.","Di titik inilah banyak tim terjebak salah kaprah: mereka memangkas aspek keandalan dan kejelasan penggunaan dengan dalih MVP, padahal yang seharusnya dipangkas adalah jumlah fitur tambahan. Produk awal tetap wajib memenuhi janji utamanya dengan bersih, aman, dan dapat diandalkan."]},{"heading":"Memetakan Ruang Eksperimen vs Ruang Standar Tinggi","paragraphs":["Cara paling jernih mendamaikan kecepatan dan kualitas adalah memisahkan dua zona kerja di dalam organisasi. Pertama, zona ketidakpastian tinggi—ketika tim belum yakin apakah suatu masalah cukup mendesak atau apakah pengguna mau membayar solusinya. Di zona ini, gunakan pendekatan MVP yang sangat ramping seperti prototipe manual, halaman uji minat, atau satu alur fitur tunggal.","Kedua, zona janji inti—ketika model nilai sudah terbukti dan pengguna mulai menggantungkan aktivitas pentingnya pada produk Anda. Di sinilah disiplin kualitas ala Good to Great harus mengambil alih kendali: perbaiki keandalan, rapikan pengalaman pengguna, dan pastikan setiap rilis tidak mencederai kepercayaan yang sudah terbentuk.","Dengan memandang MVP sebagai alat belajar yang terarah dan kesempurnaan sebagai disiplin pada pilar inti, tim tidak perlu lagi terjebak dikotomi palsu antara cepat atau bagus. Anda bergerak cepat untuk menemukan hal yang tepat, lalu bekerja tekun untuk membuatnya benar-benar kokoh."]}]',
  '["Merancang produk lengkap secara tertutup berisiko menghabiskan waktu dan modal untuk fitur yang ternyata tidak dibutuhkan pasar.","Produk Minimum Layak bertujuan memvalidasi hipotesis nilai tercepat dari perilaku nyata pengguna, bukan merilis produk yang asal jadi.","Pemangkasan dalam MVP seharusnya menyasar jumlah fitur tambahan, bukan mengorbankan keandalan, keamanan, dan janji inti produk.","Gunakan kecepatan MVP di zona ketidakpastian tinggi, lalu terapkan disiplin kualitas ketat begitu produk memasuki tahap kepercayaan massal."]'
);

INSERT OR REPLACE INTO articles (
  slug, title, subtitle, term, aliases_json, format,
  reading_time_minutes, short_definition, origin_label,
  cover_gradient, cover_image, accent_badge, published_at,
